const t={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Các khối cấu hình Klipper và macro sẵn sàng để dán - chuỗi khởi động, xử lý sợi nhựa, input shaping, bed mesh và nhiều hơn nữa. Sao chép một mẫu và thả vào printer.cfg của bạn (Config Editor là nơi thích hợp để dán)."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Trợ giúp"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Giới thiệu về Mẫu cấu hình"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Đóng"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Cách sử dụng"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Lọc theo danh mục để tìm một macro hoặc khối cấu hình."}},{t:0,b:{t:2,i:[{t:3}],s:"Đọc mô tả và những phần nó cần."}},{t:0,b:{t:2,i:[{t:3}],s:"Sao chép mẫu, dán vào cấu hình của bạn và điều chỉnh các giá trị."}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:"Đây là những gì"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Một bộ chọn lọc các khối Klipper thông dụng: gcode_macros (PRINT_START, PAUSE/RESUME, nạp/rút sợi nhựa, M600) và các phần cấu hình ([input_shaper], [bed_mesh], [firmware_retraction], …). Chúng là điểm khởi đầu - hãy đọc từng cái và tinh chỉnh cho máy của bạn."}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:"Chèn một mẫu"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Sao chép một mẫu, rồi dán vào printer.cfg của bạn - chế độ xem Raw của Config Editor là nơi tiện lợi. Sau khi lưu, khởi động lại firmware để áp dụng. Luôn xem lại các giá trị trước; các mặc định ở đây hợp lý nhưng chưa được tinh chỉnh cho máy in của bạn."}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:"Các phần cần thiết"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Mỗi mẫu liệt kê các phần cấu hình mà nó định nghĩa hoặc phụ thuộc vào. Nếu một phần đã tồn tại trong cấu hình của bạn, hãy gộp các khóa thay vì dán một bản trùng lặp (một phần trùng lặp sẽ bị từ chối khi khởi động)."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Thuật ngữ"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:"Mẫu"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Một đoạn cấu hình Klipper hoặc macro G-code sẵn sàng để dán mà bạn sao chép vào printer.cfg."}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:"gcode_macro"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Một lệnh có tên mà bạn định nghĩa trong cấu hình (ví dụ PRINT_START) để chạy một chuỗi G-code."}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:"Phần"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Một khối cấu hình [trong ngoặc], ví dụ [bed_mesh] - đơn vị mà cấu hình Klipper được nhóm vào."}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:"Danh mục"}},all:{t:0,b:{t:2,i:[{t:3}],s:"Tất cả danh mục"}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:"Sao chép"}},copied:{t:0,b:{t:2,i:[{t:3}],s:"Đã sao chép!"}},requires:{t:0,b:{t:2,i:[{t:3,v:"Các phần: "},{t:4,k:"sections"}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:"-"}}},count:{t:0,b:{t:2,i:[{t:4,k:"n"},{t:3,v:" mẫu"}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Đang tải mẫu…"}},error:{t:0,b:{t:2,i:[{t:3}],s:"Không thể tải các mẫu."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Không có mẫu nào trong danh mục này."}},retry:{t:0,b:{t:2,i:[{t:3}],s:"Thử lại"}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:"Khối cấu hình"}},macros:{t:0,b:{t:2,i:[{t:3}],s:"Macro"}}}}};export{t as default};
